text:
Pick the stores that count



Show code
tracts = FileAttachment("data/tract_combos.csv").csv({typed: false})
shapes = FileAttachment("data/pa_tracts.geojson").json()
storeTypes = FileAttachment("data/store_types.csv").csv({typed: true})
comboSummary = FileAttachment("data/combo_summary.csv").csv({typed: true})

viewof picked = Inputs.checkbox(storeTypes, {
  label: "Stores that count",
  format: d =&gt; `${d.label} (${d.stores_pa.toLocaleString()} in PA)`,
  value: storeTypes.filter(d =&gt; d.key === "supermarket" || d.key === "grocery")
})

viewof threshold = Inputs.radio(
  new Map([["1 mile urban, 10 miles rural", "1And10"],
           ["½ mile urban, 10 miles rural", "halfAnd10"],
           ["1 mile urban, 20 miles rural", "1And20"]]),
  {label: "Distance threshold", value: "1And10"})














































Show code
combo = picked.reduce((c, d) =&gt; c | (1 &lt;&lt; d.bit), 0)
largeOnly = storeTypes.filter(d =&gt; d.key === "supermarket" || d.key === "grocery")
                      .reduce((c, d) =&gt; c | (1 &lt;&lt; d.bit), 0)
allTypes = storeTypes.reduce((c, d) =&gt; c | (1 &lt;&lt; d.bit), 0)
isLA = (t, c) =&gt; (parseInt(t[`la_${threshold}`][c &gt;&gt; 2], 16) &gt;&gt; (c & 3)) & 1

byTract = new Map(tracts.map(d =&gt; [d.tract_geoid, d]))
statusOf = id =&gt; {
  const t = byTract.get(id)
  if (!t) return "Not low access"
  if (isLA(t, combo)) return "Low access with these stores"
  if (isLA(t, largeOnly)) return "Low access with large grocery retailers only"
  return "Not low access"
}

tally = c =&gt; {
  const la = tracts.filter(t =&gt; isLA(t, c))
  return {n: la.length, lila: la.filter(t =&gt; t.low_income === "1").length,
          pop: d3.sum(la, t =&gt; +t.pop2020)}
}
now = tally(combo)
base = tally(largeOnly)
beyond = c =&gt; comboSummary.find(d =&gt; d.variant === threshold && d.combo === c)?.pop_beyond ?? 0
note = combo === largeOnly ? " This is FARA and LRAM's large-retailer definition."
     : combo === allTypes ? " This is SRAM's definition: every SNAP retailer except farmers markets."
     : ""

md`${picked.length === 0
  ? "**Pick at least one store type.**"
  : `**${now.n.toLocaleString()} low-access tracts** (${now.lila.toLocaleString()} also low income), home to ${now.pop.toLocaleString()} people. **${beyond(combo).toLocaleString()} people** live beyond the threshold.&lt;br&gt;With large grocery retailers only: ${base.n.toLocaleString()} tracts (${base.lila.toLocaleString()} low income) and ${beyond(largeOnly).toLocaleString()} people beyond the threshold.${note}`}`
























































































Show code
L = require("leaflet@1.9.4")
leafletCss = html`&lt;link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.css"&gt;
&lt;style&gt;
  .osm-tiles { filter: grayscale(1) brightness(1.04) contrast(0.85); }
  body.quarto-dark .osm-tiles { filter: grayscale(1) invert(1) brightness(0.8) contrast(0.85); }
&lt;/style&gt;`

palette = ({
  "Low access with these stores": {fill: "#eb6834", opacity: 0.75},
  "Low access with large grocery retailers only": {fill: "#6da7ec", opacity: 0.6},
  "Not low access": {fill: "#000000", opacity: 0}
})

legend = html`&lt;div style="display:flex; gap:1.25rem; flex-wrap:wrap; font-size:0.85rem; margin:0.25rem 0 0.5rem;"&gt;
  ${Object.entries(palette).slice(0, 2).map(([label, s]) =&gt; html`&lt;span style="display:inline-flex; align-items:center; gap:0.4rem;"&gt;
    &lt;span style="width:14px; height:14px; border-radius:3px; background:${s.fill}; opacity:${s.opacity + 0.2};"&gt;&lt;/span&gt;${label}&lt;/span&gt;`)}
&lt;/div&gt;`

mapEl = {
  leafletCss;
  const el = html`&lt;div style="height:560px; border-radius:6px;"&gt;&lt;/div&gt;`
  // Resolves with the tract layer once Leaflet has built it, so the restyle
  // cell below waits for it instead of running too early on first load.
  let ready
  el._layer = new Promise(resolve =&gt; { ready = resolve })
  yield el

  const map = L.map(el, {preferCanvas: true, scrollWheelZoom: false, zoomSnap: 0.25})
  L.tileLayer("https://tile.openstreetmap.org/{z}/{x}/{y}.png", {
    attribution: '&copy; &lt;a href="https://www.openstreetmap.org/copyright"&gt;OpenStreetMap&lt;/a&gt; contributors',
    maxZoom: 19, className: "osm-tiles"
  }).addTo(map)

  const layer = L.geoJSON(shapes, {style: {weight: 0.4, color: "#6c757d", opacity: 0.35,
                                            fillOpacity: 0}}).addTo(map)
  map.fitBounds(layer.getBounds())
  ready(layer)
  invalidation.then(() =&gt; map.remove())
}







































Show code
// Restyle and retitle the tracts whenever the store types or threshold change
restyle = {
  const layer = await mapEl._layer
  layer.eachLayer(l =&gt; {
    const id = l.feature.properties.tract_geoid
    const status = statusOf(id)
    const s = palette[status]
    l.setStyle({fillColor: s.fill, fillOpacity: s.opacity})
    const t = byTract.get(id) ?? {}
    l.unbindTooltip().bindTooltip(
      `&lt;strong&gt;${t.county ?? ""}, tract ${id.slice(5)}&lt;/strong&gt;&lt;br&gt;` +
      `Population: ${(+t.pop2020 || 0).toLocaleString()}&lt;br&gt;${status}`,
      {sticky: true})
  })
}
